 // First read the number of tuples.
 size_t tupleCount; in >> tupleCount;
 // Then read each tuple.
 for (size_t i = 0; i < tupleCount; ++i) {
 auto loadedTuple = Tuple::deserialize(in);
 page->addTuple(std::move(loadedTuple));
 }
 in.close();
