 float sum = 0.0;
 int valid_count = 0;
 for (int i = 0; i < count; ++i) {
 if (data.timestamps[i] >= startTimestamp && data.timestamps[i] <= endTimestamp) {
 sum += data.temperatures[i];
 valid_count++;
 }
 }
 return valid_count > 0 ? sum / valid_count : 0;
}
```

